//! 🩹️ Sparse native material patches share original sealed fields and receive only explicitly authored text.
use semio_framework_value::{Number, RetirementDemand, ValueError, ValueRefusalKind, retained_clone::{RetainedCloneBinding, RetainedCloneClose, RetainedCloneGrant, RetainedCloneProgress, RetainedCloneRef, RetainedCloneStep, retained_clone_grant_admits}, retirement::shared::sealed::{SealedShared, SharedIssuer}};
use semio_framework_value_native_owned::{native_decoding::NativeDecodeControl, native_decoding::owned::NativeFlatRecord, native_decoding::owned::NativeIntrinsicSharedField};
use std::mem::ManuallyDrop;
use std::mem::size_of;
/// 👓️ A genuine native material row lends its actual sealed fields and fixed scalar values.
pub trait NativeMaterialRow<const N:usize>:NativeFlatRecord<2,N>+Sync{fn texts(&self)->[&SealedShared<String>;2];fn numbers(&self)->[Number;N];}
/// 📋️ Canonical sparse authoring values lend the original name and scalar presence without conversion.
pub trait NativeMaterialPatch<const N:usize>:Sync+'static{fn name(&self)->Option<&String>;fn numbers(&self)->[Option<f64>;N];}
/// 🧳️ Both original sources and every partial changed field remain retained until funded transfer or cancellation.
pub struct NativeMaterialPatchCursor<P:NativeMaterialPatch<N>,R:NativeMaterialRow<N>,const N:usize>{row:Option<RetainedCloneBinding>,patch:Option<RetainedCloneBinding>,texts:ManuallyDrop<[Option<SealedShared<String>>;2]>,name:NativeIntrinsicSharedField<String>,raw:ManuallyDrop<Option<R>>,output:ManuallyDrop<Option<SealedShared<R>>>,retirement:RetainedCloneClose,phase:u8,closing:bool,input:std::marker::PhantomData<fn()->P>}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native Material patch lacks its exact original sources or funded phase")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand,extra:usize)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(extra).ok_or_else(invalid)?;d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
fn child(g:RetainedCloneGrant,extra:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-extra,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl<P:NativeMaterialPatch<N>,R:NativeMaterialRow<N>,const N:usize> NativeMaterialPatchCursor<P,R,N>{
 pub fn birth_demand()->RetirementDemand{fixed(size_of::<Self>()*2)}
 pub fn begin(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::birth_demand();if !retained_clone_grant_admits(g,d){return Err(invalid());}Ok((Self{row:None,patch:None,texts:ManuallyDrop::new([None,None]),name:Default::default(),raw:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false,input:std::marker::PhantomData},receipt(d)))}
 fn metadata()->usize{2*size_of::<u8>()+2*size_of::<Option<SealedShared<String>>>()}
 fn values(row:&R,patch:&P)->[Number;N]{let values=row.numbers();let updates=patch.numbers();std::array::from_fn(|i|updates[i].map(Number::Float).unwrap_or(values[i]))}
 fn original_name<'a>(patch:RetainedCloneRef<'a,P>)->RetainedCloneRef<'a,String>{patch.project(1,|p|p.name().expect("genuine authored sparse material name"))}
 pub fn demand(&self,row:RetainedCloneRef<'_,R>,patch:RetainedCloneRef<'_,P>,body:usize)->Result<RetirementDemand,ValueError>{
  if self.closing||self.phase>=7{return Err(invalid());}row.check_binding(&self.row)?;patch.check_binding(&self.patch)?;let m=Self::metadata();
  match self.phase{0=>Ok(fixed(row.binding_copy_bytes()+m)),1=>Ok(fixed(patch.binding_copy_bytes()+m)),2=>Ok(fixed(size_of::<SealedShared<String>>()*2+m)),3=>if patch.get().name().is_some(){nested(if self.name.ready(){self.name.take_demand()?}else{self.name.demands(Self::original_name(patch),body)?},m)}else{Ok(fixed(size_of::<SealedShared<String>>()*2+m))},4=>{let texts=row.get().texts();let numbers=Self::values(row.get(),patch.get());nested(R::validation_demand([texts[0].as_str(),texts[1].as_str()],numbers),size_of::<[Number;N]>()*2+size_of::<[Option<f64>;N]>()+m)},5=>Ok(fixed(size_of::<R>()*2+size_of::<[Number;N]>()*2+size_of::<[Option<f64>;N]>()+m)),6=>nested(semio_framework_value_native_owned::native_decoding::NativeOwnedDecodeControl::shared_birth_demand::<R>(),m),_=>Err(invalid())}
 }
 pub fn advance(&mut self,row:RetainedCloneRef<'_,R>,patch:RetainedCloneRef<'_,P>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
  let d=self.demand(row,patch,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}control.checkpoint()?;let m=Self::metadata();let mut p=receipt(d);
  match self.phase{0=>{row.bind(&mut self.row,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-m,..g})?.ok_or_else(invalid)?;self.phase=1;},1=>{patch.bind(&mut self.patch,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-m,..g})?.ok_or_else(invalid)?;self.phase=2;},2=>{self.texts[0]=Some(row.get().texts()[0].try_duplicate(g)?.0);self.phase=3;},3 if patch.get().name().is_some()=>{let step=if self.name.ready(){let(name,p)=self.name.take(child(g,m))?.ok_or_else(invalid)?;self.texts[1]=Some(name);self.phase=4;RetainedCloneStep::Progress(p)}else{self.name.advance(Self::original_name(patch),control,body,child(g,m)).map_err(|e|{let mut p=e.retained_progress();p.copied_bytes=p.copied_bytes.saturating_add(m);e.with_retained_progress(p)})?};p=step.progress();p.copied_bytes=p.copied_bytes.checked_add(m).ok_or_else(invalid)?;},3=>{self.texts[1]=Some(row.get().texts()[1].try_duplicate(g)?.0);self.phase=4;},4=>{R::validate_parts([self.texts[0].as_ref().unwrap().as_str(),self.texts[1].as_ref().unwrap().as_str()],Self::values(row.get(),patch.get())).map_err(|e|e.with_retained_progress(p))?;self.phase=5;},5=>{let[id,name]=std::mem::replace(&mut*self.texts,[None,None]);*self.raw=Some(R::from_parts([id.unwrap(),name.unwrap()],Self::values(row.get(),patch.get())));self.phase=6;},6=>{let birth=SealedShared::<R>::prepare_birth(child(g,m))?;control.charge(d.capacity_bytes)?;let(output,born)=birth.materialize(self.raw.take().ok_or_else(invalid)?,SharedIssuer::owned());*self.output=Some(output);p.retained_capacity_bytes=born.retained_capacity_bytes;self.phase=7;},_=>return Err(invalid())}
  semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"native Material sparse patch")?;Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})
 }
 pub fn ready(&self)->bool{!self.closing&&self.phase==7&&self.output.is_some()}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid());}Ok(fixed(size_of::<Option<SealedShared<R>>>()*2+size_of::<u8>()))}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(SealedShared<R>,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None);}self.phase=8;Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(d))))}
 pub fn begin_close(&mut self){self.closing=true;self.name.begin_close();}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if !self.name.terminal_is_empty(){return self.name.close_demands(body);}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<R>(false,&None,body);}if self.texts.iter().any(Option::is_some){return self.retirement.next_owner_demands::<SealedShared<String>>(true,&None,body);}if self.raw.is_some(){return self.retirement.next_owner_demands::<R>(true,&None,body);}if self.output.is_some(){return self.retirement.next_owner_demands::<SealedShared<R>>(true,&None,body);}RetainedCloneBinding::demands(if self.patch.is_some(){&self.patch}else{&self.row},body)}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}if !self.name.terminal_is_empty(){return self.name.close_step(g);}if !self.retirement.is_empty(){return self.retirement.step_granted(g);}for text in self.texts.iter_mut(){if let Some(step)=self.retirement.begin_granted(text,g)?{return Ok(step);}}if let Some(step)=self.retirement.begin_granted(&mut self.raw,g)?{return Ok(step);}if let Some(step)=self.retirement.begin_granted(&mut self.output,g)?{return Ok(step);}RetainedCloneBinding::close_one(if self.patch.is_some(){&mut self.patch}else{&mut self.row},g)}
 pub fn terminal_is_empty(&self)->bool{self.row.is_none()&&self.patch.is_none()&&self.texts.iter().all(Option::is_none)&&self.raw.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.name.terminal_is_empty()}
}
impl<P:NativeMaterialPatch<N>,R:NativeMaterialRow<N>,const N:usize> Drop for NativeMaterialPatchCursor<P,R,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native Material patch retains all original and candidate issuers until funded close");}}
